11	func TestUnmarshalStringStrict(t *testing.T) {
12		fffd := string(rune(0xfffd))
13		valid := []struct{ raw, want string }{
14			{`"abc"`, "abc"},
15			{`"中文"`, "中文"},
16			{`"😀"`, "😀"},
17			{`"a�b"`, "a" + fffd + "b"}, // genuine U+FFFD written directly
