486			"json string":       `"[]"`,
487			"json number":       "42",
488			"empty array":       "[]",
489			"trailing data":     `[{"batch":"B","product":"P","quantity":1,"unit":"kg"}] {}`,
490			"truncated":         `[{"batch":"B"`,
491			"null element":      "[null]",
492			"number element":    "[1]",
493			"string element":    `["x"]`,
494			"missing batch":     `[{"product":"P","quantity":1,"unit":"kg"}]`,
495			"missing product":   `[{"batch":"B","quantity":1,"unit":"kg"}]`,
496			"missing quantity":  `[{"batch":"B","product":"P","unit":"kg"}]`,
497			"missing unit":      `[{"batch":"B","product":"P","quantity":1}]`,
