524	func TestParseManifestRecordErrorPosition(t *testing.T) {
525		content := `[{"batch":"B1","product":"P","quantity":1,"unit":"kg"},
526	                {"batch":"B2","product":"P","quantity":"bad","unit":"kg"}]`
527		_, err := ParseManifest([]byte(content))
528		var re *ManifestRecordError
529		if !errors.As(err, &re) {
530			t.Fatalf("expected ManifestRecordError, got %v", err)
531		}
532		if re.Position != 2 || re.Batch != "B2" {
533			t.Fatalf("position=%d batch=%q, want 2/B2", re.Position, re.Batch)
534		}
535	}
