605				manifest := filepath.Join(dir, "in.json")
606				if err := os.WriteFile(manifest, tc.content, 0o644); err != nil {
607					t.Fatal(err)
608				}
609	
610				var stdout bytes.Buffer
611				err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout)
612				if err == nil {
613					t.Fatal("malformed manifest must be rejected")
614				}
615				msg := err.Error()
616				for _, want := range []string{manifest, tc.pos, tc.field} {
617					if !strings.Contains(msg, want) {
618						t.Fatalf("error must mention %q: %v", want, msg)
619					}
620				}
