632					t.Fatal("rejected import must not create the registry")
633				}
634				after, rerr := os.ReadFile(manifest)
635				if rerr != nil || !bytes.Equal(after, tc.content) {
636					t.Fatal("the read-only manifest was modified")
637				}
638			})
