package batchreg

import (
	"errors"
	"fmt"
	"testing"
)

func TestZZVerify(t *testing.T) {
	cases := []struct{ name string; data []byte }{
		{"registry root raw byte", []byte("{\"version\":1,\"batches\":[],\"x\xff\":1}")},
		{"registry root lone surrogate", []byte(`{"version":1,"batches":[],"x\ud800":1}`)},
		{"registry record batch before bad key", []byte("{\"version\":1,\"batches\":[{\"batch\":\"B-002\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]}")},
		{"registry record batch after bad key", []byte("{\"version\":1,\"batches\":[{\"x\\ud800\":1,\"batch\":\"B-002\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\"}]}")},
		{"registry record not object", []byte(`{"version":1,"batches":[null]}`)},
		{"registry bad batch value encoding + bad key", []byte("{\"version\":1,\"batches\":[{\"batch\":\"B\\ud800\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]}")},
		{"registry dup batch + bad key", []byte("{\"version\":1,\"batches\":[{\"batch\":\"B1\",\"batch\":\"B2\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]}")},
		{"registry batch non-string + bad key", []byte("{\"version\":1,\"batches\":[{\"batch\":1,\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]}")},
	}
	for _, c := range cases {
		_, err := decode(c.data)
		var fe *FormatError
		if errors.As(err, &fe) {
			fmt.Printf("%-45s FormatError pos=%d batch=%q field=%q reason=%q\n", c.name, fe.Position, fe.Batch, fe.Field, fe.Reason)
		} else {
			fmt.Printf("%-45s other: %v\n", c.name, err)
		}
	}

	mcases := []struct{ name string; data []byte }{
		{"manifest r2 bad key", []byte("[{\"batch\":\"B-001\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\"},{\"batch\":\"B-002\",\"product\":\"P\",\"quantity\":2,\"unit\":\"kg\",\"x\\ud800\":1}]")},
		{"manifest bad key before batch", []byte("[{\"x\xff\":1,\"batch\":\"B-002\",\"product\":\"P\",\"quantity\":2,\"unit\":\"kg\"}]")},
		{"manifest not object", []byte(`[null]`)},
		{"manifest bad value", []byte("[{\"batch\":\"B\\ud800\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\"}]")},
		{"manifest missing batch + bad key", []byte("[{\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]")},
		{"manifest dup batch + bad key", []byte("[{\"batch\":\"B1\",\"batch\":\"B2\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x\xff\":1}]")},
		{"manifest legal FFFD name unknown", []byte("[{\"batch\":\"B\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"x�\":1}]")},
		{"manifest CJK unknown", []byte("[{\"batch\":\"B\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\",\"名称\":1}]")},
	}
	for _, c := range mcases {
		_, err := ParseManifest(c.data)
		var re *ManifestRecordError
		if errors.As(err, &re) {
			fmt.Printf("%-45s MRE pos=%d batch=%q reason=%q\n", c.name, re.Position, re.Batch, re.Reason)
		} else {
			fmt.Printf("%-45s other: %v\n", c.name, err)
		}
	}
}
